import{_ as t,o as a,c as s,a2 as d}from"./chunks/framework.BXzK3EA4.js";const k=JSON.parse('{"title":"S3 gateway","description":"","frontmatter":{"title":"S3 gateway"},"headers":[],"relativePath":"s3.md","filePath":"s3.md"}'),i={name:"s3.md"};function o(n,e,r,c,l,h){return a(),s("div",null,[...e[0]||(e[0]=[d(`<h1 id="s3-gateway" tabindex="-1">S3 gateway <a class="header-anchor" href="#s3-gateway" aria-label="Permalink to &quot;S3 gateway&quot;">​</a></h1><p><code>arkel s3</code> serves a small S3-compatible HTTP API in front of the arkel client, so backup tools that speak S3 can use Arkel as a destination: Duplicati, restic, rclone, and anything built on an AWS SDK.</p><p>It is a thin translation layer, not a second storage system. A <code>PUT</code> runs the same code as <code>arkel client put</code> (encrypt, erasure-code, distribute shards, commit the manifest), and a <code>GET</code> runs the same code as <code>arkel client get</code>.</p><h2 id="running-it" tabindex="-1">Running it <a class="header-anchor" href="#running-it" aria-label="Permalink to &quot;Running it&quot;">​</a></h2><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">arkel</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> s3</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --listen</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> 127.0.0.1:9000</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">         --index-addrs</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> http://index.pc1.arkeldata.com:8001</span></span></code></pre></div><p>That is the public index cluster. <code>--index-addrs</code> takes a comma-separated list, so add the other index nodes if you run your own network.</p><table tabindex="0"><thead><tr><th>Flag</th><th>Default</th><th>Meaning</th></tr></thead><tbody><tr><td><code>--listen</code></td><td><code>127.0.0.1:9000</code></td><td>Address to bind. Keep it on loopback or a private network.</td></tr><tr><td><code>--index-addrs</code></td><td>local cluster</td><td>Index nodes to resolve the storage pool from. Defaults to <code>127.0.0.1:8001-8003</code>; use the public cluster above for real storage.</td></tr><tr><td><code>--max-object-size</code></td><td>64 MB</td><td>Largest object accepted. Gateway memory is about four times this.</td></tr><tr><td><code>--gc-interval-secs</code></td><td>3600</td><td>How often to reclaim shards this process forwarded.</td></tr></tbody></table><p>There is <strong>no authentication</strong>. The <code>Authorization</code> header is ignored, so any non-empty access key and secret works in the client. Reachability is the boundary: bind to loopback, or attach the gateway to a container network that only your backup tool can reach.</p><h2 id="supported" tabindex="-1">Supported <a class="header-anchor" href="#supported" aria-label="Permalink to &quot;Supported&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Request</th><th>Notes</th></tr></thead><tbody><tr><td><code>GET /</code> ListBuckets</td><td>Buckets owned by the gateway&#39;s identity.</td></tr><tr><td><code>PUT /{bucket}</code> CreateBucket</td><td>Returns 200. Buckets are created implicitly by the first object write.</td></tr><tr><td><code>HEAD /{bucket}</code></td><td>Always 200, so clients proceed to upload.</td></tr><tr><td><code>GET /{bucket}?location</code></td><td>Returns <code>us-east-1</code>.</td></tr><tr><td><code>GET /{bucket}</code> ListObjects</td><td>Prefix filter, flat results, <code>IsTruncated</code> always false.</td></tr><tr><td><code>PUT /{bucket}/{key}</code> PutObject</td><td>Accepts <code>aws-chunked</code> framed bodies and echoes the request checksum.</td></tr><tr><td><code>GET /{bucket}/{key}</code> GetObject</td><td>Range requests, MD5 ETag, <code>x-amz-checksum-mode</code>.</td></tr><tr><td><code>HEAD /{bucket}/{key}</code></td><td>Reads the manifest only; no shard fetch.</td></tr><tr><td><code>DELETE /{bucket}/{key}</code></td><td>Tombstones the manifest; quota is released, shards are reclaimed by storage GC.</td></tr></tbody></table><p>A <code>HEAD</code> response has no ETag. The value is the object&#39;s MD5, which the gateway can only compute by fetching the whole object, so it reports it on <code>GET</code> instead of guessing.</p><h2 id="not-supported-yet" tabindex="-1">Not supported yet <a class="header-anchor" href="#not-supported-yet" aria-label="Permalink to &quot;Not supported yet&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Request</th><th>Effect</th><th>Status</th></tr></thead><tbody><tr><td>Multipart upload (<code>POST /{bucket}?uploads</code>, <code>PUT ?partNumber</code>, <code>POST ?uploadId</code>)</td><td>Returns <code>NotImplemented</code>. Uploads larger than the client&#39;s multipart threshold fail.</td><td>Planned</td></tr><tr><td><code>POST /{bucket}?delete</code> (multi-object delete)</td><td>Returns <code>NotImplemented</code>. Bulk delete in <code>aws s3 rm --recursive</code> and <code>rclone purge</code> fails.</td><td>Planned</td></tr><tr><td><code>DELETE /{bucket}</code></td><td>Returns <code>NotImplemented</code>. Buckets can be emptied but not removed.</td><td>Planned</td></tr><tr><td><code>delimiter</code> and <code>CommonPrefixes</code></td><td>Ignored. Listings are flat, so folder views show every key.</td><td>Planned</td></tr><tr><td>Pagination (<code>marker</code>, <code>continuation-token</code>)</td><td>Ignored. The full matching set is returned with <code>IsTruncated=false</code>, which clients accept.</td><td>Planned</td></tr><tr><td><code>CopyObject</code></td><td>Not handled. Clients fall back to download and re-upload.</td><td>Not planned</td></tr><tr><td>Presigned URLs, versioning, ACLs, tagging</td><td>Not handled.</td><td>Not planned</td></tr></tbody></table><p>Ignoring <code>max-keys</code> rather than truncating without a working continuation token is deliberate: a partial page that a client cannot continue makes it conclude objects are missing and re-upload them.</p><h2 id="limits" tabindex="-1">Limits <a class="header-anchor" href="#limits" aria-label="Permalink to &quot;Limits&quot;">​</a></h2><ul><li>One S3 object is one arkel object. An object is encrypted and erasure-coded before it leaves the gateway, so the storage cost is the erasure overhead, not the object size.</li><li>The gateway holds the whole object in memory while it works, at roughly four times the object size. Keep <code>--max-object-size</code> at or above your client&#39;s chunk size: Duplicati&#39;s default <code>dblock</code> is 50 MB, restic packs are 16 MB.</li></ul><h2 id="client-recipes" tabindex="-1">Client recipes <a class="header-anchor" href="#client-recipes" aria-label="Permalink to &quot;Client recipes&quot;">​</a></h2><p>restic:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">export</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> AWS_ACCESS_KEY_ID</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">arkel AWS_SECRET_ACCESS_KEY</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">arkel</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">restic</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -r</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> s3:http://127.0.0.1:9000/repo</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -o</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> s3.bucket-lookup=path</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> init</span></span></code></pre></div><p>Duplicati needs no S3 options beyond the endpoint. Use a <code>dblock</code> size at or below <code>--max-object-size</code>:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Server: http://arkel-s3:9000     Bucket: duplicati-unraid</span></span>
<span class="line"><span>Access key and secret: any non-empty value</span></span></code></pre></div><p>rclone works below its <code>--s3-upload-cutoff</code>; raise the cutoff past your largest file, since multipart is not implemented:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">rclone</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> copy</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ./data</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> :s3:arkel-data</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --s3-provider=Other</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --s3-endpoint=http://127.0.0.1:9000</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --s3-force-path-style</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --s3-upload-cutoff</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> 5G</span></span></code></pre></div><p>See the <a href="/cli#arkel-s3">CLI reference</a> for every flag.</p>`,24)])])}const u=t(i,[["render",o]]);export{k as __pageData,u as default};
